"""redteam 합성 엔진."""


def rt_gain(gm, ro):
    """소신호 이득."""
    return gm * ro


def rt_safe(gm):
    try:
        return rt_gain(gm, 1)
    except Exception:
        return

"""redteam 합성 엔진."""


def rt_gain(gm, ro):
    """소신호 이득."""
    return gm * ro


def rt_twice(gm):
    return rt_gain(gm, 1) + rt_gain(gm, 1)
